import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = process.cwd();
const selfPath = fileURLToPath(import.meta.url);
const full = (rel) => path.join(root, rel);
const read = (rel) => fs.readFileSync(full(rel), "utf8");
const write = (rel, content) => {
  fs.mkdirSync(path.dirname(full(rel)), { recursive: true });
  fs.writeFileSync(full(rel), content, "utf8");
};

function replaceOnce(rel, oldText, newText) {
  const source = read(rel);
  const first = source.indexOf(oldText);
  if (first < 0) throw new Error(`Expected source block not found: ${rel}`);
  if (source.indexOf(oldText, first + oldText.length) >= 0) {
    throw new Error(`Expected source block occurs more than once: ${rel}`);
  }
  write(rel, source.slice(0, first) + newText + source.slice(first + oldText.length));
}

if (!fs.existsSync(full("apps/admin-worker/src/platform-type2-claim-policy.ts"))) {
  throw new Error("Run the primary trusted-claim-policy patch first.");
}

replaceOnce(
  "apps/admin-worker/src/platform-v3-base.ts",
  "CLINICAL_DATA_MASTER_KEY?:string; TYPE2_INSURANCE_CLAIM_POLICIES_JSON?:string;",
  "CLINICAL_DATA_MASTER_KEY?:string;",
);

write(
  "apps/admin-worker/src/type2-claim-policy-registry.ts",
  `export type ReviewedType2ClaimTimingPolicy = {\n  id: string;\n  provider: string;\n  productId?: string;\n  masterDrugId?: string;\n  effectiveAt: string;\n  sourceReference: string;\n  sourceUrl?: string;\n  claimTiming: {\n    groupKey: string;\n    windowDays: number;\n    maxClaimsPerWindow: number;\n    minimumDaysBetweenClaims: number;\n    allowDistinctProductsWithinWindow: boolean;\n  };\n};\n\nexport const TYPE2_CLAIM_POLICY_REGISTRY_REVISION =\n  "type2-claim-policy-registry-v1";\n\n/**\n * Version-controlled reviewed claim-timing authority.\n *\n * Keep this empty until an authoritative payer/source document is reviewed.\n * Adding or changing an entry requires a normal Roadmap/Graph-gated PR with\n * source provenance and regression evidence. Ordinary insurance coverage rows\n * must never be promoted into this registry automatically.\n */\nconst REVIEWED_TYPE2_CLAIM_POLICIES: readonly ReviewedType2ClaimTimingPolicy[] = [];\n\nconst allowedProviders = new Set([\n  "social_security",\n  "health_insurance",\n  "armed_forces",\n  "other_organizations",\n  "supplementary",\n]);\n\nfunction boundedText(value: unknown, max: number) {\n  if (typeof value !== "string") return null;\n  const text = value.trim();\n  return text && text.length <= max ? text : null;\n}\n\nfunction positiveInteger(value: unknown, max: number) {\n  return Number.isInteger(value) && Number(value) > 0 && Number(value) <= max\n    ? Number(value)\n    : null;\n}\n\nfunction nonNegativeInteger(value: unknown, max: number) {\n  return Number.isInteger(value) && Number(value) >= 0 && Number(value) <= max\n    ? Number(value)\n    : null;\n}\n\nfunction httpsUrl(value: unknown) {\n  const text = boundedText(value, 500);\n  if (!text) return null;\n  try {\n    return new URL(text).protocol === "https:" ? text : null;\n  } catch {\n    return null;\n  }\n}\n\nexport function validateReviewedType2ClaimPolicies(\n  input: unknown,\n): ReviewedType2ClaimTimingPolicy[] {\n  if (!Array.isArray(input)) throw new Error("TYPE2_CLAIM_POLICY_ARRAY_REQUIRED");\n\n  return input.map((entry, index) => {\n    if (!entry || typeof entry !== "object") {\n      throw new Error(\`TYPE2_CLAIM_POLICY_INVALID:\${index}\`);\n    }\n    const source = entry as Record<string, unknown>;\n    const id = boundedText(source.id, 180);\n    const provider = boundedText(source.provider, 80);\n    const productId = boundedText(source.productId, 180);\n    const masterDrugId = boundedText(source.masterDrugId, 180);\n    const effectiveAt = boundedText(source.effectiveAt, 80);\n    const sourceReference = boundedText(source.sourceReference, 240);\n    const sourceUrl = source.sourceUrl === undefined\n      ? undefined\n      : httpsUrl(source.sourceUrl);\n    const timing = source.claimTiming;\n\n    if (!id || !provider || !allowedProviders.has(provider)) {\n      throw new Error(\`TYPE2_CLAIM_POLICY_ID_PROVIDER_INVALID:\${index}\`);\n    }\n    if (!productId && !masterDrugId) {\n      throw new Error(\`TYPE2_CLAIM_POLICY_TARGET_REQUIRED:\${index}\`);\n    }\n    if (!effectiveAt || !Number.isFinite(Date.parse(effectiveAt)) || !sourceReference) {\n      throw new Error(\`TYPE2_CLAIM_POLICY_PROVENANCE_REQUIRED:\${index}\`);\n    }\n    if (source.sourceUrl !== undefined && !sourceUrl) {\n      throw new Error(\`TYPE2_CLAIM_POLICY_SOURCE_URL_INVALID:\${index}\`);\n    }\n    if (!timing || typeof timing !== "object") {\n      throw new Error(\`TYPE2_CLAIM_POLICY_TIMING_REQUIRED:\${index}\`);\n    }\n\n    const claimTiming = timing as Record<string, unknown>;\n    const groupKey = boundedText(claimTiming.groupKey, 120);\n    const windowDays = positiveInteger(claimTiming.windowDays, 90);\n    const maxClaimsPerWindow = positiveInteger(claimTiming.maxClaimsPerWindow, 10);\n    const minimumDaysBetweenClaims = nonNegativeInteger(\n      claimTiming.minimumDaysBetweenClaims,\n      90,\n    );\n\n    if (\n      !groupKey ||\n      windowDays === null ||\n      maxClaimsPerWindow === null ||\n      minimumDaysBetweenClaims === null ||\n      typeof claimTiming.allowDistinctProductsWithinWindow !== "boolean"\n    ) {\n      throw new Error(\`TYPE2_CLAIM_POLICY_TIMING_INVALID:\${index}\`);\n    }\n\n    return {\n      id,\n      provider,\n      ...(productId ? { productId } : {}),\n      ...(masterDrugId ? { masterDrugId } : {}),\n      effectiveAt,\n      sourceReference,\n      ...(sourceUrl ? { sourceUrl } : {}),\n      claimTiming: {\n        groupKey,\n        windowDays,\n        maxClaimsPerWindow,\n        minimumDaysBetweenClaims,\n        allowDistinctProductsWithinWindow:\n          claimTiming.allowDistinctProductsWithinWindow,\n      },\n    };\n  });\n}\n\nexport function reviewedType2ClaimPolicies() {\n  return validateReviewedType2ClaimPolicies(REVIEWED_TYPE2_CLAIM_POLICIES);\n}\n`,
);

write(
  "apps/admin-worker/src/platform-type2-claim-policy.ts",
  `import { isRuntimeOriginAllowed } from "./platform-cors";\nimport { type V3Env } from "./platform-v3-base";\nimport { v3RequireRuntime } from "./platform-v3-session";\nimport {\n  reviewedType2ClaimPolicies,\n  TYPE2_CLAIM_POLICY_REGISTRY_REVISION,\n} from "./type2-claim-policy-registry";\n\nconst routePath = "/v1/clinical/type2/insurance-claim-policies";\n\nfunction json(request: Request, env: V3Env, body: unknown, status = 200) {\n  const origin = request.headers.get("origin");\n  return new Response(JSON.stringify(body), {\n    status,\n    headers: {\n      ...(isRuntimeOriginAllowed(origin, env)\n        ? {\n            "access-control-allow-origin": origin,\n            "access-control-allow-headers": "authorization, content-type",\n            "access-control-allow-methods": "GET, OPTIONS",\n            vary: "Origin",\n          }\n        : {}),\n      "cache-control": "no-store",\n      "content-type": "application/json; charset=utf-8",\n    },\n  });\n}\n\nexport async function type2ClaimPolicyRoute(\n  request: Request,\n  env: V3Env,\n): Promise<Response | null> {\n  const url = new URL(request.url);\n  if (url.pathname !== routePath) return null;\n\n  if (request.method === "OPTIONS") {\n    const origin = request.headers.get("origin");\n    if (!isRuntimeOriginAllowed(origin, env)) {\n      return new Response(null, { status: 403 });\n    }\n    return new Response(null, {\n      status: 204,\n      headers: {\n        "access-control-allow-origin": origin,\n        "access-control-allow-headers": "authorization, content-type",\n        "access-control-allow-methods": "GET, OPTIONS",\n        vary: "Origin",\n      },\n    });\n  }\n\n  if (request.method !== "GET") {\n    return json(request, env, { error: "method_not_allowed" }, 405);\n  }\n\n  const runtime = await v3RequireRuntime(request, env);\n  if (!runtime) return json(request, env, { error: "auth_required" }, 401);\n  if (!runtime.user.permissions.includes("type2")) {\n    return json(request, env, { error: "type2_permission_required" }, 403);\n  }\n\n  try {\n    const now = Date.now();\n    return json(request, env, {\n      schemaVersion: 1,\n      authority: "trusted_runtime",\n      registryRevision: TYPE2_CLAIM_POLICY_REGISTRY_REVISION,\n      generatedAt: new Date(now).toISOString(),\n      expiresAt: new Date(now + 5 * 60 * 1000).toISOString(),\n      policies: reviewedType2ClaimPolicies(),\n    });\n  } catch {\n    return json(request, env, { error: "claim_policy_registry_invalid" }, 503);\n  }\n}\n`,
);

write(
  "apps/admin-worker/test/type2-claim-policy-boundary.test.ts",
  `import { describe, expect, it } from "vitest";\nimport { type2ClaimPolicyRoute } from "../src/platform-type2-claim-policy";\nimport {\n  reviewedType2ClaimPolicies,\n  validateReviewedType2ClaimPolicies,\n} from "../src/type2-claim-policy-registry";\n\ndescribe("trusted Type-2 claim policy boundary", () => {\n  it("keeps the production registry empty until reviewed authority exists", () => {\n    expect(reviewedType2ClaimPolicies()).toEqual([]);\n  });\n\n  it("requires reviewed provenance and bounded timing metadata", () => {\n    const policies = validateReviewedType2ClaimPolicies([{\n      id: "tamin:wegovy:2026-09",\n      provider: "social_security",\n      productId: "WEGOVY-025",\n      effectiveAt: "2026-09-01T00:00:00.000Z",\n      sourceReference: "reviewed-tamin-policy-2026-09",\n      sourceUrl: "https://example.test/reviewed-policy",\n      claimTiming: {\n        groupKey: "wegovy-strength-switch",\n        windowDays: 30,\n        maxClaimsPerWindow: 2,\n        minimumDaysBetweenClaims: 28,\n        allowDistinctProductsWithinWindow: true,\n      },\n    }]);\n    expect(policies[0]?.claimTiming.minimumDaysBetweenClaims).toBe(28);\n    expect(policies[0]?.sourceReference).toBe("reviewed-tamin-policy-2026-09");\n  });\n\n  it("fails closed on malformed timing configuration", () => {\n    expect(() => validateReviewedType2ClaimPolicies([{\n      id: "bad",\n      provider: "social_security",\n      productId: "WEGOVY-025",\n      effectiveAt: "2026-09-01T00:00:00.000Z",\n      sourceReference: "reviewed-policy",\n      claimTiming: {\n        groupKey: "wegovy",\n        windowDays: 30,\n        maxClaimsPerWindow: 2,\n        minimumDaysBetweenClaims: -1,\n        allowDistinctProductsWithinWindow: true,\n      },\n    }])).toThrow(/TYPE2_CLAIM_POLICY_TIMING_INVALID/);\n  });\n\n  it("requires runtime authentication before exposing the registry", async () => {\n    const response = await type2ClaimPolicyRoute(\n      new Request("https://worker.example.test/v1/clinical/type2/insurance-claim-policies"),\n      {\n        ADMIN_ORIGIN: "https://rc.example.test",\n        SESSION_SECRET: "test-session-secret",\n      },\n    );\n    expect(response?.status).toBe(401);\n    expect(await response?.json()).toEqual({ error: "auth_required" });\n  });\n});\n`,
);

replaceOnce(
  "docs/architecture/RUNTIME_OF_RECORD.md",
  "Reviewed claim-timing rules remain server-side in the Cloudflare Worker configuration and are exposed only",
  "Reviewed claim-timing rules live in a version-controlled Cloudflare Worker registry in the private repository and are exposed only",
);

fs.unlinkSync(selfPath);
console.log("TYPE2_CLAIM_POLICY_REGISTRY_HARDENING_APPLIED");
